export function build(manim) {
 const {Scene,Text,SurroundingRectangle,VGroup,Arrow,Dot,FadeIn,Create,Indicate,FadeOut}=manim;
 const scene=new Scene();
 const labels=["业务应用 / AI","Data Fabric","原始数据源"];
 const xs=[-4.4,0,4.4];
 const groups=labels.map((s,i)=>{const t=Text(s,{color:"#dff8ff"}).scale_to_fit_width(i===1?2.4:2.8).move_to([xs[i],0.5,0]);const b=SurroundingRectangle(t,{buff:0.35,color:i===1?"#54e9ff":"#588cff"});return VGroup(t,b);});
 const a=Arrow([-2.8,0.5,0],[-1.7,0.5,0],{color:"#54e9ff"});
 const b=Arrow([1.7,0.5,0],[2.8,0.5,0],{color:"#54e9ff"});
 const caption=Text("连接管理 · 身份与权限 · 查询路由",{color:"#9baeff"}).scale_to_fit_width(8.2).move_to([0,-1.6,0]);
 scene.play(...groups.map(g=>FadeIn(g)),{run_time:1.3});
 scene.play(Create(a),Create(b),FadeIn(caption),{run_time:1.5});
 const p=Dot({radius:0.11,color:"#54e9ff"}).move_to([-2.8,0.5,0]);
 scene.play(FadeIn(p),{run_time:0.4});
 scene.play(p.animate.move_to([-1.7,0.5,0]),{run_time:1.5});
 scene.play(Indicate(groups[1]),{run_time:1.2});
 scene.play(p.animate.move_to([2.8,0.5,0]),{run_time:1.5});
 scene.play(Indicate(groups[2]),{run_time:1.2});
 scene.play(FadeOut(p),{run_time:0.5});scene.wait(0.5);return scene;
}

SELECT id
FROM sample.orders
ORDER BY id ASC;

export function build(manim) {
 const {Scene,Text,SurroundingRectangle,VGroup,FadeIn,Indicate,Arrow,Create}=manim;
 const scene=new Scene();
 const texts=["首批：1，2","续批：3","结果完整"];
 const xs=[-4.3,0,4.3];
 const boxes=texts.map((s,i)=>{const t=Text(s,{color:i===2?"#7bf5c4":"#dff8ff"}).scale_to_fit_width(2.5).move_to([xs[i],0.3,0]);return VGroup(t,SurroundingRectangle(t,{buff:0.4,color:i===2?"#7bf5c4":"#54e9ff"}));});
 const caption=Text("batch_size = 2",{color:"#94aaff"}).scale_to_fit_width(3.8).move_to([0,2.2,0]);
 const tail=Text("取回所有批次，明确结果是否完整",{color:"#dff8ff"}).scale_to_fit_width(8.4).move_to([0,-1.7,0]);
 scene.play(FadeIn(caption),FadeIn(boxes[0]),{run_time:1.5});
 scene.play(Indicate(boxes[0]),{run_time:1.2});
 scene.play(Create(Arrow([-2.6,0.3,0],[-1.65,0.3,0],{color:"#54e9ff"})),{run_time:1});
 scene.play(FadeIn(boxes[1]),{run_time:1.2});
 scene.play(Indicate(boxes[1]),{run_time:1.2});
 scene.play(Create(Arrow([1.65,0.3,0],[2.6,0.3,0],{color:"#7bf5c4"})),{run_time:1});
 scene.play(FadeIn(boxes[2]),FadeIn(tail),{run_time:1.3});
 scene.wait(0.5);return scene;
}
